INSERT INTO books (id, title, author, description, price, picture) VALUES
(1, '1984 - Corc Oruell', 'Corc Oruell', 'Corc Oruellin 1984 romanı totalitarizmin dəhşətlərini ən çılpaq şəkildə üzə çıxaran möhtəşəm distopik əsərdir. Hadisələr Okeaniya adlı uydurma dövlətdə cərəyan edir. Cəmiyyət Böyük Qardaş tərəfindən hər an və hər yerdə izlənilir. İnsanların şəxsi həyatı, düşüncələri və hətta duyğuları belə dövlətin tam nəzarəti altındadır. Tele-ekranlar vasitəsilə hər bir vətəndaşın addımı 24 saat boyunca izlənməkdədir. Hərbi Təbliğat Nazirliyi keçmişi yenidən yazaraq tarixi istədiyi kimi dəyişdirir. Sevgi Nazirliyi insanlara işgəncə verərək rejimə itaət etdirir. Bol Nazirliyi isə qıtlığı idarə edir və insanları yoxsulluqda saxlayır. Həqiqət Nazirliyi yalanları həqiqət kimi təqdim edir. Okeaniyada azad düşüncə ən ağır cinayət sayılır. Bu cinayət Düşüncə Cinayəti kimi tanınır və cəzası ölümdür. Baş qəhrəman Uinston Smit Həqiqət Nazirliyində çalışan sıravi bir məmurdur. Onun vəzifəsi köhnə qəzet məqalələrini partiyanın yeni xəttinə uyğunlaşdırmaqdır. Uinston rejimin yalanlarından və təzyiqlərindən gizlicə nifrət edir. O, sistemə qarşı daxili bir üsyan hiss edir. Uinston gizli bir gündəlik tutmağa başlayır. Bu gündəlik onun ilk böyük Düşüncə Cinayətidir. O, gündəliyinə rejimin əleyhinə fikirlər yazır. Uinstonun həyatı Culiya ilə tanış olduqdan sonra tamamilə dəyişir. Culiya da rejimə qarşı daxilən üsyan edən gənc bir qadındır. Onlar gizlicə görüşməyə və sevgilərini yaşamağa başlayırlar. Bu sevgi rejimə qarşı ən böyük meydan oxumadır. Onlar qadağan olunmuş duyğuları yaşayaraq azadlıq hiss edirlər. Uinston və Culiya Partiya əleyhinə olan gizli təşkilatla əlaqə qurmağa çalışırlar. Onlar Obrayen adlı yüksək rütbəli məmura inanırlar. Obrayen onları Partiyaya qarşı mübarizə aparan Qardaşlıq təşkilatına daxil etdiyini bildirir. Lakin bu, rejim tərəfindən qurulmuş dəhşətli bir tələdir. Uinston və Culiya gizli görüşdükləri evdə qəflətən həbs olunurlar. Onları Sevgi Nazirliyinin dəhşətli zindanlarına aparırlar. Uinston zindanda ağır fiziki və mənəvi işgəncələrə məruz qalır. Obrayen şəxsən onun işgəncələrini idarə edir. Rejimin məqsədi Uinstonu sadəcə öldürmək deyil. Onlar onun ruhunu və düşüncəsini tamamilə sınmaq istəyirlər. Obrayen Uinstona Böyük Qardaşı sevdirməyə çalışır. İnsanın iradəsi və kimliyi sistemli şəkildə məhv edilir. 101-ci otaq hər kəsin ən böyük qorxusunun reallaşdığı yerdir. Uinstonun ən böyük qorxusu siçovullardır. O, 101-ci otaqda siçovul hücumu ilə hədələnir. Dəhşətli qorxu içində olan Uinston Culiyaya xəyanət edir. O, siçovulların özünə deyil Culiyaya hücum etməsini qışqırır. Bu xəyanət Uinstonun sonuncu mənəvi qalanı da dağıdır. O, azad iradəsini və insanlığını tamamilə itirir. Fiziki olaraq azad edildikdən sonra Uinston artıq keçmiş Uinston deyildir. O, kafedə oturub təklikdə içki içir. Culiya ilə yenidən qarşılaşır, lakin aralarındakı hiss tamamilə ölüb. Onlar bir-birlərinə xəyanət etdiklərini etiraf edirlər. Uinston artıq rejimə qarşı heç bir nifrət hiss etmir. O, Böyük Qardaşı səmimi qəlbdən sevməyə başlayır. Əsər insan iradəsinin totalitar rejim qarşısındakı acizliyini göstərir. Roman dilin düşüncəyə necə təsir etdiyini açib göstərir.', 12.50, 'https://images.unsplash.com/photo-1544947950-fa07a98d237f?w=300&h=300&fit=crop'),
(2, 'Əli və Nino - Qurban Səid', 'Qurban Səid', 'Əli və Nino romanı Şərq və Qərb mədəniyyətlərinin qovuşduğu Bakı şəhərində cərəyan edən möhtəşəm bir sevgi dastanındır. Əli xan Şirvanşir kübar bir müsəlman ailəsinin övladıdır. O, Şərq ənənələrinə, tarixinə və öz köklərinə dərindən bağlıdır. Nino Qipiani isə Avropa tərbiyəsi görmüş gözəl bir gürcü knyaz qızıdır. O, Qərb dəyərlərini, azadlığı və müasir həyat tərzini üstün tutur. İki gənc bir-birini dəli kimi sevir. Lakin onların sevgisi fərqli dini və mədəni dünyaların toqquşması ilə qarşılaşır. Əlinin ailəsi Şərq adətlərini qorumağa çalışır. Ninonun ailəsi isə Qərb həyat tərzinə daha yaxındır. Hadisələr Birinci Dünya Müharibəsi və Azərbaycan Xalq Cümhuriyyətinin qurulduğu dövrdə baş verir. Bakı neft bumu sayəsində zənginləşən və inkişaf edən bir şəhərdir. Şəhərdə həm Şərq memarlığı, həm də Avropa dəbdəbəsi yan-yana yaşayır. Əli və Nino bu mürəkkəb mühitdə sevgilərini qorumağa çalışırlar. Nino Əlinin dünyasını anlamağa səy göstərir. Əli də Ninonun azadlıq sevər xarakterinə hörmətlə yanaşır. Lakin erməni mənşəli Məlik Naxararyanın Ninonu qaçırması hadisələri kəskinləşdirir. Əli sevgilisini xilas etmək üçün Naxararyanı təqib edir və onu öldürür. Bu namus məsələsi Əlini Bakıdan qaçmağa məcbur edir. O, Dağıstan dağlarında gizlənməli olur. Nino sevdiyi adamın arxasınca dağlara gedir. Onlar sadə dağ kəndində evlənirlər və xoşbəxt günlər yaşayırlar. Dağ həyatı Ninoya çətin gəlsə də, sevgisi hər şeyə üstün gəlir. Rusiya imperiyasının süqutundan sonra Azərbaycan müstəqillik qazanır. Əli və Nino Bakıya qayıdırlar. Əli Xalq Cümhuriyyətinin xarici işlər nazirliyində işləməyə başlayır. Onlar Bakıda böyük bir evdə yaşayırlar və övladları dünyaya gəlir. Nino diplomatiya qəbullarında öz savadı ilə hamını valeh edir. Lakin bolşevik təhlükəsi Azərbaycanın müstəqilliyini hədələyir. Qırmızı Ordu Bakıya doğru irəliləməyə başlayır. Əli ailəsini təhlükəsiz yerə göndərir. O, vətənini qorumaq üçün Gəncəyə gedir. Əli körpü üzərində bolşeviklərlə qəhrəmancasına döyüşür. O, vətənin müstəqilliyi uğrunda mütəşəkkil müqavimətdə həlak olur. Əlinin ölümü həm böyük bir sevgini, həm də bir cümhuriyyətin taleyini bitirir. Əsər sadəcə bir sevgi hekayəsi deyildir. Bu roman Şərq və Qərb sivilizasiyalarının dialoqudur. Müəllif Qurban Səid Bakının abu-havasını ustalıqla təsvir edir. Şəhərin neft qoxuyan küçələri oxucunun gözü önündə canlanır. Əsərdə Qafqaz xalqlarının adət-ənənələri geniş yer alır. Qonaqfərvərlik, namus və mərdlik kimi anlayışlar vurğulanır. Müharibənin gətirdiyi fəlakətlər insan talelərini darmadağın edir. Əlinin vətənpərvərliyi hər bir oxucuda dərin ehtiram yaradır. Nino obrazı güclü və fədakar qadın rəmzidir. Onların sevgisi bütün maneələri aşmağı bacarır. Roman dünyanın bir çox dillərinə tərcümə olunub. Əsərin həqiqi müəllifinin kimliyi uzun illər mübahisə mövzusu olmuşdur. Məhəmməd Əsəd bəy və ya Yusif Vəzir Çəmənzəminli müəllif kimi göstərilir. Lakin əsərin bədii dəyəri mübahisələrdən uzaqdır. Kitab oxucunu tarixi bir gəzintiyə çıxarır. Azərbaycanın müstəqillik mübarizəsi dəqiq faktlarla təsvir edilir.', 10.00, 'https://images.unsplash.com/photo-1543002588-bfa74002ed7e?w=300&h=300&fit=crop'),
(3, 'Cinayət və Cəza - Fyodor Dostoyevski', 'Fyodor Dostoyevski', 'Fyodor Dostoyevskinin Cinayət və Cəza romanı dünya ədəbiyyatının ən böyük psixoloji şahəsərlərindən biridir. Əsərin baş qəhrəmanı Rodion Raskolnikov kasıb bir tələbədir. O, Sankt-Peterburqun rütubətli və qaranlıq küçələrində ac-yalavac yaşayır. Raskolnikov özünəməxsus bir fəlsəfi nəzəriyyə cızır. Bu nəzəriyyəyə görə insanlar iki kateqoriyaya bölünürlər. Birinci kateqoriya adi insanlardır ki, onlar qanunlara itaət etməlidirlər. İkinci kateqoriya isə fövqəladə insanlardır ki, onlar böyük məqsədlər üçün qanunları poza bilərlər. Napoleon kimi şəxsiyyətlər fövqəladə insanlara misaldır. Raskolnikov özünün hansı kateqoriyaya ait olduğunu yoxlamaq istəyir. O, qocalan və qəddarlığı ilə tanınan sələmçi qadını öldürmək qərarına gəlir. Sələmçi Alyona İvanovna insanları soyur və istismar edir. Raskolnikov onun pulunu götürərək faydalı işlərə xərcləmək niyyətindədir. O, balta ilə qoca qadının mənzilinə daxil olur. Raskolnikov sələmçi qadını amansızlıqla qətlə yetirir. Lakin hadisə yerinə gözlənilmədən qadının bacısı Lizaveta gəlir. Raskolnikov şahid buraxmamaq üçün Lizavetanı da öldürməyə məcbur olur. Cinayətdən sonra Raskolnikov dəhşətli psixoloji sarsıntı keçirir. O, götürdüyü pulları istifadə edə bilmir və onları gizlədir. Onun fiziki sağlamlığı kəskin şəkildə pisləşir. Raskolnikov qızdırma içində günlərlə çarpayıda yatır. Cinayət vicdan əzabı kimi onun ruhunu gəmirməyə başlayır. O, insanlardan tamamilə təcrid olunur. Hətta anası və bacısı Dunya gəldikdə bile onlardan qaçır. Müstəntiq Porfiri Petrovich cinayəti araşdırmağa başlayır. O, Raskolnikovun yazmış olduğu məqaləni oxuyub onun nəzəriyyəsindən xəbərdar olur. Porfiri Petrovich Raskolnikovla psixoloji oyunlar oynayır. O, Raskolnikovun vicdanının onu ifşa edəcəyini bilir. Bu mürəkkəb dövrdə Raskolnikov Sonya Marmeladova ilə tanış olur. Sonya ailəsini saxlamq üçün özünü qurban verən fədakar bir qızdır. Sonya dərin dini inanca və təmiz qəlbə malikdir. Raskolnikov öz sirrini ilk dəfə Sonya açır. O, cinayət törətdiyini Sonyaya etiraf edir. Sonya onu mühakimə etmir, əksinə ona acıyır. Sonya Raskolnikova cinayətini etiraf etməyi və cəzasını çəkməyi tövsiyə edir. O, Raskolnikova Sibirə sürgünə belə getməyə hazır olduğunu bildirir. Vicdan əzabına dözə bilməyən Raskolnikov polis bölməsinə gedir. O, cinayətini rəsmən etiraf edir. Raskolnikov Sibirə katorğaya sürgün edilir. Sonya da onun arxasıyca Sibirə gedir. Sürgündə Raskolnikov uzun müddət öz nəzəriyyəsinin səhv olduğunu qəbul etmək istemir. Lakin Sonyanın qarşılıqsız sevgisi və səbri onun qəlbini yumşaldır. Raskolnikov dini inanca və mənəvi təmizlənməyə üz tutur. O, nəhayət öz səhvini anlayır və peşmanlıq duyur. Roman insanın daxili aləmini dəqiqliklə təsvir edir. Dostoyevski insan psixologiyasının ən dərin qatlarına nüfuz edir. Vicdan azabı fiziki işgəncədən daha ağırdır. Hər bir cinayət özü ilə bir cəza gətirir. Cəza sadəcə qanuni deyil, həm də mənəvidir. Sankt-Peterburq şəhəri əsərdə qaranlıq bir obraz kimi təqdim olunur. Şəhərin boğucu havası qəhrəmanın ruh halını əks etdirir.', 15.00, 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=300&h=300&fit=crop'),
(4, 'Balaca Şahzadə - Antuan de Sent-Ekzüperi', 'Antuan de Sent-Ekzüperi', 'Balaca Şahzadə Antuan de Sent-Ekzüperinin qələmə aldığı dünya şöhrətli sehrli bir əsərdir. Kitab uşaqlar üçün yazılsa da, əslində böyüklər üçün dərin filosofi mənaya malikdir. Hadisələr təyyarəçinin Böyük Səhrada qəzaya uğraması ilə başlayır. Təyyarəçi səhrada tək qalır və təyyarəsini təmir etməyə çalışır. Su ehtiyatı azdır və vəziyyət son dərəcə böhranlıdır. Gözlənilmədən onun qarşısına balaca bir oğlan uşağı çıxır. Bu balaca oğlan Balaca Şahzadədir. O, təyyarəçidən özü üçün bir qoyun şəkli çəkməsini xahiş edir. Təyyarəçi onun bu qəribə istəyinə təəccüblənir. Onlar dostlaşırlar və Balaca Şahzadə öz planetindən danışmağa başlayır. Onun planeti B-612 adlı kiçik bir asteroiddir. Bu planetdə üç vulkan və bir neçə zərərli baobab tumurcuqları var. Balaca Şahzadə hər gün planetini təmizləyir və baobabları təmizləyir. Planetində həm də çox nazlı və gözəl bir Qızılgül var. Balaca Şahzadə bu Qızılgülü çox sevir və ona baxır. Lakin Qızılgülün nazı və inciklikləri Balaca Şahzadəni yorur. O, planetini tərk edib kainatı gəzmək qərarına gəlir. Balaca Şahzadə müxtəlif asteroidləri ziyarət edir. İlk planetdə yalnız əmr verməyi sevən bir Kral yaşayır. İkinci planetdə özünü bəyənmiş və tərifi sevən bir Adam var. Üçüncü planetdə utancını unutmaq üçün içki içən bir Sərxoş yaşayır. Dördüncü planetdə davamlı olaraq ulduzları sayan bir İş adamı var. Beşinci planetdə hər dəqiqə fənəri yandıran və söndürən bir Fənərçi yaşayır. Altıncı planetdə isa kitablar yazan, lakin heç vaxt səyahət etməyən bir Coğrafiyaçı var. Bu planetlərdəki böyüklər Balaca Şahzadəyə çox qəribə gəlir. O, böyüklərin mənasız işlərlə məşğul olduğunu düşünür. Yeddinci planet kimi Balaca Şahzadə Yer kürəsinə gəlir. Yer kürəsi çox böyükdür və burada milyonlarla insan yaşayır. Balaca Şahzadə səhrada bir Tülkü ilə tanış olur. Tülkü ona ehliləşdirmək anlayışını izah edir. Ehliləşdirmək dostluq və bağ yaratmaq deməkdir. Tülkü ona öz gizli həqiqətini açır. Əsas məqamları yalnız qəlblə görmək mümkündür. Ən vacib şeyləri gözlə görmək olmaz. Balaca Şahzadə öz Qızılgülünün bənzərsiz olduğunu anlayır. Çünki o, məhz həmin Qızılgülə vaxt ayırmışdır. İnsan ayırdığı vaxta görə məsuliyyət daşıyır. Təyyarəçi də Balaca Şahzadədən çox şey öyrənir. Səhrada su ehtiyatı bitir və onlar quyu axtarmağa başlayırlar. Onlar səhranın ortasında möcüzəvi şəkildə bir quyu tapırlar. İçdikləri su sadəcə bədənlərini deyil, ruhlarını da sərinlədir. Balaca Şahzadə artıq öz planetinə və Qızılgülünə qayıtmaq istəyir. O, Yerdəki fiziki bədəninin çox ağır olduğunu bilir. Planetinə qayıtmaq üçün gizli bir İlanla razılaşır. İlanın sancması ilə o, planetinə qayıdacaqdır. Təyyarəçi bu ayrılıqdan böyük kədər duyur. Balaca Şahzadə ona ulduzlara baxmağı tövsiyə edir. O bildirir ki, ulduzlara baxanda onun gülüşünü eşidəcəkdir. Balaca Şahzadə yox olur və yalnız bədəni Yerdə qalır. Təyyarəçi təyyarəsini düzəldib evinə qayıdır.', 8.00, 'https://images.unsplash.com/photo-1532012197267-da84d127e765?w=300&h=300&fit=crop'),
(5, 'Körpüdəki Kimyagər - Paulo Koelyo', 'Paulo Koelyo', 'Paulo Koelyonun Kimyagər romanı insanın öz taleyini və həyatının mənasını kəşf etməsi haqqında ilhamverici bir şahəsərdir. Əsərin baş qəhrəmanı Santyaqo adlı gənc bir Əndəlüs çobanıdır. Santyaqo qoyunlarını otararaq İspaniyanın kəndlərini gəzir. O, azad həyatı və səyahət etməyi çox sevir. Santyaqo eyni yuxunu iki dəfə üst-üstə görür. Yuxuda balca bir uşaq onu Misir piramidalarına aparır. Uşaq ona piramidaların yaxınlığında gizlədilmiş böyük bir xəzinə olduğunu bildirir. Santyaqo bu yuxunun mənası haqqında düşünməyə başlayır. O, Tarifa şəhərində bir qaraçı qadının yanına gedir. Qaraçı qadın yuxunun həqiqi olduğunu və Piramidalara getməli olduğunu deyir. Daha sonra Santyaqo özünü Məliksadiq kimi təqdim edən köhnə bir kralla tanış olur. Kral ona Şəxsi Əfsanə anlayışını izah edir. Şəxsi Əfsanə insanın həyatda gerçəkləşdirmək istədiyi ən böyük arzusudur. Bütün kainat insanın öz Şəxsi Əfsanəsini reallaşdırması üçün ona kömək edir. Kral Santyaqoya yol göstərən Urim və Tummim adlı iki sehrli daş verir. Santyaqo qoyunlarını sataraq Afrika sahillərinə keçir. O, Mərakeşin Təncər şəhərinə gəlir. Lakin burada ilk gündəcə bütün pulunu bir oğruya iyrənc şəkildə kaptırır. Santyaqo pulsuz və çarəsiz qalır. O, bir billur qablar satan tacirin yanında işə düzəlir. Santyaqo zəhmətkeşliyi və yeni ideyaları ilə tacirin dükanını zənginləşdirir. O, burada bir il işləyərək böyük məbləğdə pul qazanır. Santyaqo İspaniyaya qayıdıb təzədən qoyun almaq haqqında düşünür. Lakin o, Şəxsi Əfsanəsini yarımçıq qoymamaq qərarına gəlir. Santyaqo Səhra karvanına qoşularaq Misirə doğru yola düşür. Karvanda o, kimyagərlik elmini öyrənmək istəyən bir ingilislə tanış olur. İngilis kitablar vasitəsilə kainatın dilini anlamağa çalışır. Santyaqo isə kainatın dilini səhranı müşahidə edərək öyrənir. Səhrada qəbilələr arasında müharibə başlayır. Karvan Əl-Fəyyum vahəsində dayanmağa məcbur olur. Santyaqo vahədə quyu başında Fatimə adlı gözəl bir qızla tanış olur. O, Fatiməyə ilk baxışdan vurulur. Fatimə Səhranın qızıdır və Santyaqonun öz yoluna davam etməsini dəstəkləyir. Santyaqo səhrada iki qartalın uçuşunu izləyərək vahəyə hücum olacağını əvvəlcədən duyur. O, bu xəbərdarlığı vahə rəhbərlərinə bildirir. Vahə hücumun qarşısını uğurla alır və Santyaqo böyük mükafat qazanır. Vahədə Santyaqo həqiqi Kimyagərlə tanış olur. Kimyagər ona Piramidalara gedən yolda bələdçilik etməyi təklif edir. Onlar birlikdə səhranın dərinliklərinə doğru yola düşürlər. Kimyagər Santyaqoya öz qəlbini dinləməyi öyrədir. Qəlb kainatın ruhu ilə birbaşa əlaqədədir. Onlar səhra döyüşçüləri tərəfindən əsir alınırlar. Kimyagər döyüşçülərə Santyaqonun küləyə çevrilə biləcəyini söyləyir. Santyaqo üç gün ərzində qəlbi, səhra, külək və günəşlə danışır. O, kainatın ruhu ilə vəhdət təşkil edərək möcüzə göstərir. Döyüşçülər heyran qalır və onları azad edirlər. Nəhayət Santyaqo Misir piramidalarına çatır. O, göz yaşları tökərək xəzinəni qazmağa başlayır. Lakin bu zaman onun yanına hərbi qaçqınlar gəlir. Onlar Santyaqonu döyür və pulunu əlindən alırlar.', 11.00, 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=300&h=300&fit=crop'),
(6, 'Səfillər - Viktor Hüqo', 'Viktor Hüqo', 'Viktor Hüqonun Səfillər romanı fransız ədəbiyyatının və dünya klassikasının ən böyük şahəsərlərindən biridir. Əsər 19-cu əsr Fransasında ədalətsizlik, yoxsulluq və mərhəmət mövzularını dərindən araşdırır. Baş qəhrəman Jan Valjan bir tikə çörək oğurladığı üçün 19 il ağır katorğa cəzasına məkum edilir. O, həbsxanadan çıxdıqda cəmiyyət tərəfindən kənarlaşdırılır və hər kəs ona cinayətkar kimi baxır. Jan Valjanın həyatı yepiskop Miriel ilə tanışlıqdan sonra kökündən dəyişir. Yepiskop ona səmimi qonaqfərvərlik göstərir və gümüş şamdanları hədiyyə edərək onun ruhunu xilas edir. Bu xeyirxahlıq Jan Valjanın qəlbində böyük bir dönüş yaradır. O, keçmişini gizlədərək cəmiyyətə faydalı bir insan olmağa qərar verir. Jan Valjan cənab Madlen adı altında yeni bir şəhərdə fabrik açır və meri seçilir. O, yoxsullara yardım edir və şəhərin inkişafı üçün çalışır. Lakin polis müfəttişi Javel onu daim təqib edir. Javel qanunlara kor-koranə sadiq olan və insanın dəyişə biləcəyinə inanmayan qəddar bir adamdır. Əsərdə digər mühüm fəciəvi obraz Fantinadır. Fantina uşağını saxlamaq üçün hər şeyini qurban verən fədakar bir anadır. O, ağır şəraitdə çalışır və səhhətini itirərək gənc yaşda vəfat edir. Jan Valjan Fantinaya söz verir ki, onun qızı Kozettaya öz övladı kimi baxacaqdır. Jan Valjan Kozettanı qəddar Tenardye ailəsinin əlindən xilas edir. Tenardye ailəsi hərislik və əxlaqsızlığın simvoludur. Jan Valjan və Kozetta Parisə köçürlər və burada gizli bir həyat sürürlər. Kozetta böyüyür və gözəl bir gənc qız olur. O, Marius adlı gənc bir inqilabçıya vurulur. Marius Parisdəki tələbə üsyanlarının fəal iştirakçısıdır. 1832-ci il Paris üsyanı əsərin ən gərgin səhnələrindən birini təşkil edir. Tələbələr barrikadalar quraraq azadlıq və ədalət uğrunda mübarizə aparırlar. Jan Valjan Mariusu xilas etmək üçün barrikadalara gedir. O, yaralı Mariusu kanalizasiya boruları vasitəsilə daşıyaraq ölümün pəncəsindən qurtarır. Barrikadalarda Jan Valjan müfəttiş Javeli də əsir alır, lakin onu öldürmək əvəzinə azad edir. Javel Jan Valjanın bu mərhəməti qarşısında dərin mənəvi böhran keçirir. Qanunla mərhəmət arasında qalan Javel özünü Sen çayına ataraq intihar edir. Marius və Kozetta evlənirlər və xoşbəxt bir həyat qururlar. Jan Valjan öz keçmişini Mariusa etiraf edir və onlardan uzaqlaşır. Yaşlaşmış Jan Valjan təklikdə son günlərini yaşayır. Marius onun həyatını xilas etdiyini öyrəndikdə dərin peşmanlıq duyur. Kozetta və Marius onun yanına tələsirlər. Jan Valjan sevdiklərinin qollarında dinc şəkildə vəfat edir. Əsər cəmiyyətin tapdaladığı insanların acınacaqlı taleyini göstərir. Hüqo yoxsulluğun insanı cinayətə sövq etdiyini vurğulayır. Mənəvi dirçəliş və bağışlamaq romanın əsas ideyasıdır. Jan Valjan obrazı insani dəyərlərin və fədakarlığın zirvəsidir. Javel isə kor-koranə ədalətin təhlükələrini simvolizə edir. Kozetta ümidin və paklığın rəmzidir. Tenardyelər cəmiyyətin mənəvi çürüməsini əks etdirir. Əsərdə Parisin tarixi, küçələri və sosial yapısı incəliklə təsvir olunur. Hüqo oxucunu cəmiyyətin sosial problemləri haqqında düşünməyə məcbur edir. Roman boyu gərginlik və emosionallıq yüksək səviyyədə qalır. İnsanın öz qismətini dəyişmək gücü nümayiş etdirilir. Sevgi və xeyirxahlıq hər cür şərə qalib gəlir. Əsər dünya ədəbiyyatında silinməz izlər qoymuşdur. Müəllifin təsvir qabiliyyəti oxucunu valeh edir. Hər bir cümlə dərin humanist mənaya malikdir.', 18.50, 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=300&h=300&fit=crop'),
(7, 'Qürur və Qərəz - Ceyn Ostin', 'Ceyn Ostin', 'Ceyn Ostinin Qürur və Qərəz romanı ingilis ədəbiyyatının ən məşhur romantik şahəsərlərindən biridir. Əsərdə 19-cu əsrin əvvəllərində İngiltərədəki cəmiyyət, nikah və sinfi fərqlər ustalıqla təsvir olunur. Bennet ailəsinin beş subay qızı var və anaları onları varlı adamlarla evləndirmək həsrətindədir. Baş qəhrəman Elizabet Bennet ağıllı, müstəqil düşüncəli və iti zəkası ilə seçilən bir qızdır. Cənab Darsi isə son dərəcə varlı, kübar, lakin zahirən soyuq və qürurlu bir zadəngəndədir. Onların ilk tanışlığı bal rəqsi zamanı tutarsız bir təəssüratla başlayır. Darsi Elizabeti yetərincə gözəl hesab etmədiyini bildirərək onunla rəqs etməkdən imtina edir. Elizabet bu qürurlu davranışı gördükdə Darsiyə karşı dərin bir qərəz bəsləməyə başlayır. Darsinin dostu cənab Bingli isə Elizabetin bacısı Ceynə vurulur. Ceyn təmiz qəlbli və xeyirxah bir qızdır. Lakin Darsi Binglinin Ceynlə evlənməsinə mane olmağa çalışır, çünki Bennet ailəsinin sosial statusunu aşağı hesab edir. Bu hadisə Elizabetin Darsiyə olan nifrətini daha da artırır. Zabit Uikhem də Elizabetin etibarını qazanaraq Darsi haqqında yalan hekayələr danışır. Elizabet Uikhemin yalanlarına inanır və Darsini daha da qəddar biri kimi tanıyır. Zaman keçdikcə Darsi Elizabetin zəkasına və xarakterinə heyran olmağa başlayır. O, sinfi fərqlərə baxmayaraq Elizabetə evlilik təklifi edir. Lakin onun təklifi qürurlu və təhqiredici bir tonda olur. Elizabet bu təklifi kəskin şəkildə rədd edir və Darsini bacısının xoşbəxtliyini məhv etməkdə günahlandırır. Darsi Elizabetə yazdığı məktubda bütün həqiqətləri acıqlayır. O, Uikhemin əslində necə şərəfsiz və həris bir insan olduğunu sübut edir. Elizabet bu məktubu oxuduqdan sonra öz qərəzli yanaşmasından utanc duyur. O, Darsini yanlış qiymətləndirdiyini anlayır. Elizabet xalası və əmisi ilə Darsinin Pemberli mülkünə gəzintiyə gedir. O, Darsinin evindəki xidmətçilərdən onun necə xeyirxah və alicənab bir bəy olduğunu öyrənir. Darsi burada Elizabetlə qarşılaşır və ona qarşı son dərəcə nəzakətli davranır. Elizabetin kiçik bacısı Lidiya Uikhem ilə qaçaraq Bennet ailəsini böyük bir rüsvayçılıqla üz-üzə qoyur. Darsi gizlicə Uikhemə böyük məbləğdə pul ödəyərək onun Lidiya ilə evlənməsini təmin edir. O, bu alicənablığı Bennet ailəsinin adını xilas etmək və Elizabetə olan sevgisi üçün edir. Elizabet Darsinin bu fədakarlığını öyrəndikdə ona qarşı dərin bir sevgi və minnətdarlıq hiss edir. Darsi bir daha Elizabetə evlənmək təklifi edir. Bu dəfə Elizabet onun təklifini böyük sevinclə qəbul edir. Ceyn və Bingli də barışaraq evlənirlər. Əsər ilk təəssüratların necə aldadıcı ola biləcəyini göstərir. Qürur insanın gözünü kor edir, qərəz isə həqiqəti görməyə mane olur. Elizabet öz qərəzini, Darsi isə qürurunu yenməyi bacarır. Ceyn Ostinin zərif yumoru və satirik dili əsəri daha da cazibədar edir. Qadınların həmin dövrdəki sosial statusu və evlilik məcburiyyəti kəskin tənqid olunur. Əsərdəki dialoqlar zəriflik və iti zəka nümunəsidir. Bennet anasının xarakteri oxucuda təbəssüm yaradır. Cənab Bennetin sakit və satirik yanaşması marqlıdır. Pemberli mülkü Darsinin daxili gözəlliyinin simvoludur. Roman romantik ədəbiyyatın zirvələrindən biri hesab olunur. Müəllif insan psixologiyasını və cəmiyyət münasibətlərini dəqiqliklə təsvir edir. Əsər dəfələrlə film və seriallara uyğunlaşdırılmışdır. Elizabet Bennet obrazı güclü qadın xarakterinin rəmzidir. Darsi isə ədəbiyyat tarixinin ən sevilən kişi obrazlarındandır. Kitab oxucuya insanları mühakimə etməkdə tələsməməyi öyrədir. Sevgi hər cür sosial baryeri və qərəzi aşmağa qadirdir. Romanı oxumaq böyük bir mənəvi zövq verir. Ceyn Ostinin qələmi oxucunu 19-cu əsr İngiltərəsinə aparır.', 11.50, 'https://images.unsplash.com/photo-1543002588-bfa74002ed7e?w=300&h=300&fit=crop'),
(8, 'Çovğunlu Təpələr - Emili Bronte', 'Emili Bronte', 'Emili Brontenin Çovğunlu Təpələr romanı ingilis ədəbiyyatının ən qaranlıq, ehtiraslı və unudulmaz əsərlərindən biridir. Əsər Hitklif və Ketrin arasındakı dağıdıcı və əbədi sevgidən bəhs edir. Hadisələr Yorkshire-in soyuq və kimsəsiz təpəliklərində cərəyan edir. Cənab İrnşou Liverpuldan küçədə tapdığı kimsəsiz bir qaraçı oğlanını evə gətirir və ona Hitklif adını verir. İrnşounun oğlu Hındli Hitklifə nifrət edir və ona xidmətçi kimi davranır. Qızı Ketrin isə Hitkliflə qısa zamanda dərin bir bağ qurur. Onlar təpəliklərdə birlikdə vaxt keçirərək azadlıq hiss edirlər. Lakin Cənab İrnşounun ölümündən sonra Hındli Çovğunlu Təpələrin sahibi olur və Hitklifə işgəncələr verir. Ketrin varlı və tərbiyəli cənab Edqar Lintonla tanış olur. O, sosial statusunu qorumaq üçün Edqarla evlənməyə qərar verir. Ketrin Hitklifi sevdiyini, lakin onunla evlənməyin onu alçaldacağını bildirir. Hitklif bu sözləri gizlicə eşidir və böyük bir qırıqlıqla Çovğunlu Təpələri tərk edir. Bir neçə ildən sonra Hitklif zəngin və intiqam hissi ilə dolu bir adam kimi qayıdır. O, Hındlinin qumar borclarından istifadə edərək Çovğunlu Təpələri ələ keçirir. Hitklif Lintonun bacısı İzabellanı özünə aşiq edir və onunla evlənərək intiqam alır. Ketrin Hitklifin qayıdışından sonra ağır mənəvi sarsıntı keçirir və xəstələnir. O, qızı Kozettaya bənzər kiçik Ketrini dünyaya gətirərək vəfat edir. Ketrinin ölümü Hitklifi tamamilə dəliyə döndərir. O, Ketrinin ruhuna yalvarır ki, onu yalnız buraxmasın və daim təqib etsin. Hitklifin intiqam hissi növbəti nəslə də keçir. O, Hındlinin oğlu Xartonu savadsız saxlayaraq onu xidmətçi edir. Ketrinin qızı kiçik Ketrini öz zəif oğlu Lintonla evlənməyə məcbur edir. Bu yolla Hitklif Lintonların da mülkü olan Skvayn Qranjı ələ keçirir. Lakin bu intiqam Hitklifə heç bir huzur gətirmir. O, Ketrinin ruhunu hər yerdə görməyə başlayır. Hitklif yeməkdən və içməkdən imtina edərək tədricən solur. O, yalnız Ketrinlə qovuşacağı günü gözləyir. Nəhayət Hitklif Ketrinin otağında vəfat edir. Kəndlilər onların ruhlarının təpəliklərdə azad şəkildə gəzdiyini deyirlər. Hitklifin ölümündən sonra kiçik Ketrin və Xarton bir-birini sevməyə başlayırlar. Onlar Çovğunlu Təpələrə yenidən işıq və huzur gətirirlər. Əsər sevgi və intiqamın insan ruhunu necə məhv edə biləcəyini gösterir. Hitklif ədəbiyyat tarixinin ən mürəkkəb anti-qəhrəmanlarından biridir. Onun sevgisi müqəddəs olduğu qədər də dəhşətli və dağıdıcıdır. Ketrin və Hitklif bir-birlərinin ruhunun eyni olduğunu düşünürlər. Emili Brontenin tək romanı olan bu əsər böyük sensasiya yaratmışdır. Yorkshire-in sərt təbiəti obrazların daxili dünyasını əks etdirir. Romanın strukturu mürəkkəbdir və müxtəlif ravilər tərəfindən danışılır. Qulluqçu Nelli Din hadisələrin əsas şahididir. Cənab Lokvud isə kənardan gələn bir müşahidəçidir. Əsərdəki ehtiras və vəhşilik Victorian dövrü üçün çox kəskin idi. Roman oxucunu qaranlıq və emosional bir burulğana çəkir. Müəllifin dilinin gücü və təsvirləri heyranlıq doğurur. Sevgi burada romantik deyil, varlıq mübarizəsidir. Hitklifin faciəsi oxucuda həm nifrət, həm də acıma hissi yaradır. Çovğunlu Təpələr qotik ədəbiyyatın ən gözəl nümunələrindəndir. Kitab boyu gərginlik bir an belə azalmır. Əsər dəfələrlə kinoya və teatra uyğunlaşdırılmışdır. Bu kitabı oxumaq insan psixologiyasının dərinliklərinə enməkdir. Emili Brontenin dahiliyi bu əsərdə tam parlaqlığı ilə görünür.', 13.00, 'https://images.unsplash.com/photo-1544947950-fa07a98d237f?w=300&h=300&fit=crop'),
(9, 'Dorian Qreyin Portreti - Oskar Uayld', 'Oskar Uayld', 'Oskar Uayldın Dorian Qreyin Portreti romanı estetizm və mənəvi süqut mövzusunda yazılmış ən parlaq əsərdir. Əsərin baş qəhrəmanı Dorian Qrey müstəsna füsunkar və gözəl bir gəncdir. Rəssam Bəzil Holvord Dorianın gözəlliyinə valeh olaraq onun tam boy portretini çəkir. Bəzil bu portretə öz ruhunu və sənətkar sevgisini qoyur. Dorian rəssamın emalatxanasında lord Henri Uotton ilə tanış olur. Lord Henri hedonist fəlsəfənin tərəfdarıdır və gəncliklə gözəlliyin yeganə ali dəyər olduğunu müdafiə edir. O, Dorianın beyninə cavanlıq və gözəllik haqqında təhlükəli fikirlər yeridir. Dorian portretə baxarkən öz gəncliyinin solacağını düşünüb dəhşətə gəlir. O, arzu edir ki, portret onun əvəzinə qocalsın, özü isə həmişə gənc qalsın. Bu təhlükəli arzu möcüzəvi şəkildə gerçəkləşir. Dorian gənc teatr aktrisası Sibilla Vane vurulur. Sibilla Dorianın sevgisi sayəsində səhnədə pis oynamağa başlayır, çünki həqiqi sevgini tapmışdır. Dorian onun sənətdən uzaqlaşdığını görüb onu amansızcasına tərk edir. Çarəsiz qalan Sibilla intihar edir. Dorian evə qayıtdıqda portretdə ilk qəddarlıq izini və dəyişikliyi görür. Portretdəki Dorianın dodaqlarında qəddar bir təbəssüm yaranmışdır. Dorian portretin onun günahlarını öz üzərinə götürdüyünü anlayır. O, portreti çardaqda gizlədir ki, heç kim bu dəhşətli sirri görməsin. Dorian lord Henrinin təsiri altında günah və ləzzət dolu bir həyat sürməyə başlayır. O, hər cür əxlaqsızlığa və cinayətə əl atır, lakin zahirən mələk kimi gənc və təmiz qalır. İllər keçir, Dorian heç qocalmır, lakin portret dəhşətli bir heyvana çevrilir. Rəssam Bəzil Dorianı düz yola dəvət etmək üçün onun yanına gəlir. Dorian Bəzilə gizli portreti göstərir. Bəzil portretdəki dəhşətli eybəcərliyi görüb şoka düşür. Dorian sirrini bildiyi üçün Bəzili amansızlıqla qətlə yetirir. O, cəsədi yox etmək üçün kimyaçı dostunu hədələyir. Dorianın ətrafındakı bütün insanlar mənəvi bəla və fəlakətlə üzləşirlər. Dorian öz vicdan əzabından qaçmaq üçün tiryək xanələrinə gedir. Sibillanın qardaşı Ceyms Vane intiqam almaq üçün Dorianı təqib edir. Lakin Ceyms təsadüfən ov zamanı öldürülür. Dorian yeni bir həyata başlamaq və yaxşı adam olmaq istəyir. Lakin portretə baxdıqda dəyişiklik olmadığını, əksinə daha da iyrençləşdiyini görür. Dorian anlayır ki, onun yaxşılıqları da özünü aldatmaqdan başqa bir şey deyildir. O, vicdanının rəmzi olan bu eybəcər portreti məhv etmək qərarına gəlir. Dorian Bəzili öldürdüyü bıçaqla portretə zərbə endirir. Xidmətçilər qışqırıq səsini eşidib çardağa qaçırlar. Onlar divarda gənc və gözəl Dorianın portretini görürlər. Döşəmədə isə qocalan, eybəcər və sinəsində bıçaq olan bir cəsəd yatır. Xidmətçilər cəsədi yalnız barmağındakı üzükdən tanıyırlar. Əsər sənət, gözəllik və mənəviyyat arasındakı mürəkkəb əlaqəni göstərir. Oskar Uayldın zərif estetizmi və incə satira dili romanı bənzərsiz edir. Lord Henrinin aforizmləri oxucunu dərindən düşündürür. İnsanın öz ruhunu satmasının acı nəticələri nümayiş etdirilir. Zahiri gözəllik daxili çürüməni gizlədə bilməz. Portret Dorianın vicdanının və ruhunun güzgüsüdür. Əsər Viktoriya dövrünün ikiüzlü əxlaq anlayışını tənqid edir. Uayldın tək romanı olan bu əsər ədəbiyyat tarixinin incisidir. Roman boyu gərginlik və estetik zövq paralel irəliləyir. Kitab oxucuya həqiqi gözəlliyin mənəviyyatda olduğunu öyrədir. Bu şahəsəri oxumaq böyük bir intellektual zövqdür.', 10.50, 'https://images.unsplash.com/photo-1532012197267-da84d127e765?w=300&h=300&fit=crop'),
(10, 'Çevrilmə - Frans Kafka', 'Frans Kafka', 'Frans Kafkanın Çevrilmə əsəri absürd ədəbiyyatın və modernizmin ən məşhur şahəsərlərindən biridir. Əsərin baş qəhrəmanı Qreqor Zamza sadə bir parça satıcısıdır. O, ailəsini, valideynlərini və bacısını saxlamaq üçün yorulmadan çalışır. Bir sabah Qreqor Zamza narahat yuxulardan oyanarkən özünün dəhşətli bir həşərata çevrildiyini görür. O, arxası üstə yatıb və çoxlu incə ayaqlarının çabaladığını müşahidə edir. Qreqor ilk olaraq bu vəziyyətin dəhşətini deyil, işə gecikəcəyini düşünür. O, ailəsinin borclarını ödəyən yeganə şəxsdir. Qreqorun otaqdan çıxmadığını görən ailəsi və iş yerindən gələn müdir qapını döyürlər. Qreqor böyük çətinliklə qapını açır. Müdir və ailəsi onun həşərata çevrildiyini görüncə böyük şok və dəhşət keçirirlər. Müdir qorxudan qaçır, atası isə onu əsa ilə vuraraq otağına qovur. Qreqor artıq insan dilində danışa bilmir, yalnız qəribə səslər çıxarır. Ailəsi onu otaqda təcrid edir. Yalnız bacısı Qreta ona acıyır və yemək gətirir. Qreta Qreqorun artıq təzə yeməkləri deyil, çürümüş qalıqları yediyini görür. Bacısı onun otaqda rahat hərəkət etməsi üçün mebelləri çıxarmaq istəyir. Lakin anası Qreqorun insanlıq ümidini itirməməsi üçün mebellərin qalmasını istəyir. Bir gün Qreqor otaqdan çıxdıqda atası ona alma atmağa başlayır. Almalarından biri Qreqorun kürəyinə batır və orada çürüyərək ağır yara yaradır. Qreqorun fiziki vəziyyəti kəskin pisləşir. Ailə maliyyə çətinliyi çəkdiyi üçün evin otaqlarını üç kirayəçiyə verir. Ailə üzvləri işləməyə başlayırlar və Qreqor artıq onlar üçün böyük bir yükə çevrilir. Bir axşam bacısı Qreta kirayəçilər üçün skripka çalır. Qreqor musiqinin gözəlliyinə valeh olaraq otaqdan bayıra çıxır. Kirayəçilər dəhşətli həşəratı görüb evi tərk edəcəklərini və pul ödəməyəcəklərini bildirirlər. Bacısı Qreta artıq bu yaratığa dözə bilməyəcəklərini və ondan qurtulmalı olduqlarını deyir. O, bu yaratığın Qreqor olmadığını iddia edir. Qreqor bacısının bu sözlərindən dərin mənəvi sarsıntı keçirir. O, ailəsinə olan sevgisini qoruyaraq təklikdə və kədər içində otağında vəfat edir. Səhər xidmətçi qadın onun quru cəsədini tapır və zibil kimi tullayır. Ailə üzvləri Qreqorun ölümündən sonra böyük bir rahatlıq və yüngüllük hiss edirlər. Onlar şəhər kənarına gəzintiyə çıxırlar və gələcək planlar qururlar. Valideynlər bacı Qretanın artıq gözəl bir gənc qıza çevrildiyini görürlər. Əsər modern cəmiyyətdə insanın özünə və cəmiyyətə özgələşməsini təsvir edir. Kafka fərdin ailə və sistem qarşısındakı acizliyini ustalıqla gösterir. Qreqorun həşərata çevrilməsi onun daxili yalnızlığının mənəvi təzahürüdür. İnsanın dəyəri yalnız faydalı olduğu müddətcə mövcuddur. Faydasız olduqda ən yakın doğmaları bile ondan imtina edir. Əsərin dili son dərəcə sadə, lakin dərin psixolojidir. Absürd hadisə son derece təbii bir dildə anlatılır. Kafka oxucuda dərin boğuntu və çürümə hissiyyatı yaradır. Roman dünya ədəbiyyatında eksprssionizmin ən parlaq nümunəsidir. Çevrilmə əsəri hər bir oxucunu öz həyatı haqqında düşünməyə vadar edir. Bu kitabı mütaliə etmək mənəvi bir silkələnmədir. Frans Kafkaın üslubu sadə görünsə də, mənaca son dərəcə zəngindir. Kitab boyunca gərginlik və maraq bir an belə azalmır. Çevrilmə əsəri klassik ədəbiyyatın zirvələrindən biri hesab olunur. Frans Kafkaın yaradıcılığı dünya ədəbiyyatşünaslığında geniş tədqiq olunub. Hər bir fəsil oxucuda yeni sual və düşüncələr doğurur. Əsərdəki obrazların daxili dünyası incəliklə və ustalıqla işlənmişdir.', 7.50, 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=300&h=300&fit=crop'),
(11, 'Aprel və Küçə Oyunları - Stefan Zveyq', 'Stefan Zveyq', 'Stefan Zveyqin bu füsunkar əsəri insan psixologiyasının ən incə və gizli məqamlarına işıq tutur. Müəllif qəhrəmanların daxili sarsıntılarını və duyğularını böyük ustalıqla qələmə almışdır. Hekayələrdə uşaqlıq xatirələri, gənclik ehtirasları və həyatın gözlənilməz dönüşləri təsvir olunur. Zveyq hər bir obrazın daxili dünyasını bir psixoloq dəqiqliyi ilə analiz edir. Əsər oxucunu insanın mənəvi axtarışları haqqında düşünməyə vadar edir. Qəhrəmanların qarşılaşdığı emosional böhranlar oxucuda dərin empati hissi oyadır. Müəllifin tərzi son dərəcə axıcı, emosional və təsiredicidir. Zveyq cəmiyyətin yazılmamış qaydalarını və fərdin bu qaydalar qarşısındakı acizliyini göstərir. Hər bir hekayə özlüyündə böyük bir həyat dərsi barındırır. İnsanın öz hissləri ilə mübarizəsi əsərin ana xəttini təşkil edir. Avstriya ədəbiyyatının bu böyük ustadı oxucunu ilk səhifədən sehrləyir. Kitabda keçmişə olan həsrət və itirilmiş imkanlar mövzusu qabarıq şəkildə işlənmişdir. Müəllif kədəri və sevinci eyni anda hiss etdirmək bacarığına malikdir. Zveyqin qələmindən çıxan hər bir cümlə dərin mənəvi yük daşıyır. Bu əsər dünya ədəbiyyatında özünəməxsus yeri olan dəyərli bir xəzinədir. Əsərdəki hadisələr məntiqi ardıcıllıqla və ustalıqla qurulmuşdur. Əsər həm ədəbiyyatsevərlər, həm də tədqiqatçılar üçün dəyərli mənbədir. Əsər bədii dilin gücünü və insan taleyinin mürəkkəbliyini birləşdirir. Stefan Zveyq bu romanda insan ruhunun ən dərin qatlarına işıq salır. Aprel və Küçə Oyunları oxunduqca insanın həyat və dəyərlər haqqında düşüncələri dərinləşir. Kitabdakı dialoqlar dərin fəlsəfi və psixoloji məna daşıyır. Hər bir fəsil oxucuda yeni sual və düşüncələr doğurur. Müəllifin təsvir bacarığı oxucunu hadisələrin canlı şahidinə çevirir. Bu kitab tənqidçilər tərəfindən dəfələrlə yüksək qiymətləndirilmişdir. Stefan Zveyqın yaradıcılığı dünya ədəbiyyatşünaslığında geniş tədqiq olunub. Əsərdəki hər bir təfərrüat müəllifin böyük ustalığından xəbər verir. Bu əsər dünya ədəbiyyatı tarixinin şah əsərlərindən biri kimi qəbul edilir. Kitab mütaliə mədəniyyətinin formalaşmasında mühüm rol oynayır. Kitab boyunca gərginlik və maraq bir an belə azalmır. Hər bir mütaliəsevər bu kitabı kitabxanasında saxlamalıdır. Aprel və Küçə Oyunları əsəri dünya ədəbiyyatının ən çox oxunan kitablarından biri sayılır. Əsərdəki simvolizm oxucuya çoxqatlı məna qatları açır. Əsər zaman keçdikcə yeni nəsillər tərəfindən yenidən kəşf edilir. Bu kitab oxucuya həm zövq, həm də dərin düşüncə bəxş edir. Stefan Zveyqın bu əsəri illər keçdikcə öz aktuallığını itirməmişdir. Aprel və Küçə Oyunları əsərinin təsiri kino, teatr və digər sənət sahələrinə də yayılmışdır. Oxucu kitabı bitirdikdən sonra dünyaya fərqli gözlə baxmağa başlayır. Kitab oxucunu dərin düşüncələrə və mənəvi bir səyahətə aparır. Bu roman insan psixologiyasını və cəmiyyətin ziddiyyətlərini dəqiqliklə əks etdirir. Aprel və Küçə Oyunları əsəri klassik ədəbiyyatın zirvələrindən biri hesab olunur. Kitabın son səhifəsi oxucuda uzun müddət unudulmayan təsir buraxır. Əsərdəki obrazların daxili dünyası incəliklə və ustalıqla işlənmişdir. Stefan Zveyqın dili zəngin, obrazlı və son dərəcə təsiredicidir. Roman boyunca hər bir personaj öz unikal inkişaf yolunu keçir. Bu roman nəsillər boyu öz təsirini itirməyən əbədi bir dəyərdir. Müəllifin yaratdığı atmosfer oxucunu əsərin dünyasına dərindən çəkir. Oxucu əsər boyu personajların taleyinə dərindən bağlanır. Bu roman insan iradəsinin sınağa çəkildiyi anları təsvir edir. Roman insan taleyinin, sevginin və mübarizənin dərin təhlilini verir. Əsərdə işlənən mövzular bu gün də öz aktuallığını qoruyur.', 8.00, 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=300&h=300&fit=crop'),
(12, 'Bəyaz Gecələr - Fyodor Dostoyevski', 'Fyodor Dostoyevski', 'Fyodor Dostoyevskinin Bəyaz Gecələr əsəri Sankt-Peterburqun nağılvari atmosferində cərəyan edən romantik və həzin bir sevgi hekayəsidir. Əsərin baş qəhrəmanı yalnızlıq içində yaşayan və xəyallar dünyasında ömür sürən gənc bir xəyalpərəstdir. O, Peterburqun küçələrində təkbaşına gəzərkən körpünün üzərində ağlayan Nastenka adlı gənc bir qızla tanış olur. Nastenka bir ildir ki, sevdiyi adamın yolunu gözləyir və onun qayıdacağına olan ümidini itirmək üzrədir. Xəyalpərəst Nastenkanın kədərinə şərik olur və ona təsəlli verməyə çalışır. Dörd bəyaz gecə boyunca onlar bir-birlərinə daxili dünyalarını, arzularını və kədərlərini danışırlar. Xəyalpərəst Nastenkaya qarşı dərin və təmənnasız bir sevgi hiss etməyə başlayır. Lakin Nastenka onu yalnız sadiq bir dost kimi görür. Nastenkanın sevdiyi adam nəhayət şəhərə qayıdır və Nastenka onunla gedir. Xəyalpərəst yenidən öz təkliyinə və xəyallar dünyasına qayıdır, lakin Nastenkaya qarşı heç bir kin bəsləmir. O, yaşadığı bu dörd gecəlik xoşbəxtliyə görə taleyinə minnətdar olur. Əsər insanın daxili yalnızlığını və təmənnasız sevginin aliliyini təsvir edir. Dostoyevskinin erkən dövr yaradıcılığına aid olan bu povest poetik dili ilə seçilir. Peterburq gecələrinin təsviri obrazların ruhi halı ilə tam uyğunluq təşkil edir. Əsər oxucuya saf duyğuların və fədakarlığın gözəlliyini göstərir. Roman fərdin cəmiyyətlə münasibətini bütün incəlikləri ilə göstərir. Kitab oxucunu dərin düşüncələrə və mənəvi bir səyahətə aparır. Hər bir fəsil oxucuda yeni sual və düşüncələr doğurur. Bu əsər həyatın mənası haqqında əbədi suallara işıq salır. Əsərdə işlənən mövzular bu gün də öz aktuallığını qoruyur. Bu əsər dünya ədəbiyyatı tarixinin şah əsərlərindən biri kimi qəbul edilir. Bu kitab oxucuya həm zövq, həm də dərin düşüncə bəxş edir. Fyodor Dostoyevski bu romanda insan ruhunun ən dərin qatlarına işıq salır. Bəyaz Gecələr əsərinin təsiri kino, teatr və digər sənət sahələrinə də yayılmışdır. Fyodor Dostoyevskiın bu əsəri illər keçdikcə öz aktuallığını itirməmişdir. Hər bir mütaliəsevər bu kitabı kitabxanasında saxlamalıdır. Fyodor Dostoyevskiın üslubu sadə görünsə də, mənaca son dərəcə zəngindir. Fyodor Dostoyevskiın yaradıcılığı dünya ədəbiyyatşünaslığında geniş tədqiq olunub. Əsərdəki obrazların daxili dünyası incəliklə və ustalıqla işlənmişdir. Əsərdəki hadisələr məntiqi ardıcıllıqla və ustalıqla qurulmuşdur. Müəllifin təsvir bacarığı oxucunu hadisələrin canlı şahidinə çevirir. Fyodor Dostoyevskiın dili zəngin, obrazlı və son dərəcə təsiredicidir. Roman insan taleyinin, sevginin və mübarizənin dərin təhlilini verir. Əsərdəki simvolizm oxucuya çoxqatlı məna qatları açır. Bu roman insan psixologiyasını və cəmiyyətin ziddiyyətlərini dəqiqliklə əks etdirir. Kitabın strukturu diqqətlə düşünülmüş və mükəmməl qurulmuşdur. Kitabdakı dialoqlar dərin fəlsəfi və psixoloji məna daşıyır. Kitab mütaliə mədəniyyətinin formalaşmasında mühüm rol oynayır. Bu roman insan iradəsinin sınağa çəkildiyi anları təsvir edir. Əsər həm ədəbiyyatsevərlər, həm də tədqiqatçılar üçün dəyərli mənbədir. Bu roman nəsillər boyu öz təsirini itirməyən əbədi bir dəyərdir. Əsər zaman keçdikcə yeni nəsillər tərəfindən yenidən kəşf edilir. Kitabın son səhifəsi oxucuda uzun müddət unudulmayan təsir buraxır. Roman boyunca hər bir personaj öz unikal inkişaf yolunu keçir. Müəllifin yaratdığı atmosfer oxucunu əsərin dünyasına dərindən çəkir. Kitab boyunca gərginlik və maraq bir an belə azalmır. Əsərin sonu oxucuda dərin düşüncə və hisslər buraxır. Əsər bədii dilin gücünü və insan taleyinin mürəkkəbliyini birləşdirir. Bəyaz Gecələr əsəri dünya ədəbiyyatının ən çox oxunan kitablarından biri sayılır. Bu kitab tənqidçilər tərəfindən dəfələrlə yüksək qiymətləndirilmişdir.', 6.50, 'https://images.unsplash.com/photo-1543002588-bfa74002ed7e?w=300&h=300&fit=crop'),
(13, 'Balaca Prens - Antuan de Sent-Ekzüperi', 'Antuan de Sent-Ekzüperi', 'Antuan de Sent-Ekzüperinin Balaca Prens əsəri həm uşaqlar, həm də böyüklər üçün yazılmış dərin fəlsəfi bir nağıldır. Əsər böyüklərin dünyasındakı məntiqsizlikləri və dəyərlərin təhrif olunmasını uşaq gözü ilə tənqid edir. Baş qəhrəman səhrada təyyarəsi qəzaya uğrayan bir pilotdur. O, burada B-612 adlı kiçik bir planetdən gələn Balaca Prens ilə qarşılaşır. Balaca Prens öz planetindəki nazlı Qızılgülü tərk edərək digər planetləri gəzməyə çıxmışdır. Səyahəti boyunca o, padşah, şöhrətpərəst, sərxoş, iş adamı, fənərçi və coğrafiyaşünasla tanış olur. Bu obrazların hər biri böyüklərin aludə olduğu mənasız ehtirasları simvolizə edir. Yer kürəsinə gələn Balaca Prens burada Tülkü ilə dostlaşır. Tülkü ona həyatın ən böyük sirrini öyrədir: ''İnsan yalnız qəlbi ilə yaxşı görə bilər, əsl mahiyyəti gözlə görmək mümkün deyil.'' Balaca Prens başa düşür ki, öz planetindəki gülünü digər minlərlə güldən fərqli edən şey ona sərf etdiyi vaxt və sevgidir. Əsər dostluq, məsuliyyət, sevgi və sadəlik kimi insani dəyərləri təbliğ edir. Sent-Ekzüperinin öz illüstrasiyaları ilə bəzədilmiş bu kitab dünya ədəbiyyatının ən çox oxunan incilərindəndir. Hər yaşda oxunduqda fərqli bir məna kəsb edən bu şahəsər mənəvi bir xəzinədir. Antuan de Sent-Ekzüperiın bu əsəri illər keçdikcə öz aktuallığını itirməmişdir. Müəllifin yaratdığı atmosfer oxucunu əsərin dünyasına dərindən çəkir. Bu əsər dünya ədəbiyyatı tarixinin şah əsərlərindən biri kimi qəbul edilir. Əsərin sonu oxucuda dərin düşüncə və hisslər buraxır. Antuan de Sent-Ekzüperiın yaradıcılığı dünya ədəbiyyatşünaslığında geniş tədqiq olunub. Əsərdə işlənən mövzular bu gün də öz aktuallığını qoruyur. Müəllifin təsvir bacarığı oxucunu hadisələrin canlı şahidinə çevirir. Bu kitab tənqidçilər tərəfindən dəfələrlə yüksək qiymətləndirilmişdir. Əsər həm ədəbiyyatsevərlər, həm də tədqiqatçılar üçün dəyərli mənbədir. Əsərdəki obrazların daxili dünyası incəliklə və ustalıqla işlənmişdir. Antuan de Sent-Ekzüperiın dili zəngin, obrazlı və son dərəcə təsiredicidir. Bu roman insan iradəsinin sınağa çəkildiyi anları təsvir edir. Oxucu əsər boyu personajların taleyinə dərindən bağlanır. Kitabın strukturu diqqətlə düşünülmüş və mükəmməl qurulmuşdur. Əsərdəki hər bir təfərrüat müəllifin böyük ustalığından xəbər verir. Bu kitab oxucuya həm zövq, həm də dərin düşüncə bəxş edir. Balaca Prens oxunduqca insanın həyat və dəyərlər haqqında düşüncələri dərinləşir. Kitab oxucunu dərin düşüncələrə və mənəvi bir səyahətə aparır. Bu əsər həyatın mənası haqqında əbədi suallara işıq salır. Roman fərdin cəmiyyətlə münasibətini bütün incəlikləri ilə göstərir. Roman boyunca hər bir personaj öz unikal inkişaf yolunu keçir. Bu roman nəsillər boyu öz təsirini itirməyən əbədi bir dəyərdir. Kitabdakı dialoqlar dərin fəlsəfi və psixoloji məna daşıyır. Balaca Prens əsərinin təsiri kino, teatr və digər sənət sahələrinə də yayılmışdır. Hər bir mütaliəsevər bu kitabı kitabxanasında saxlamalıdır. Balaca Prens əsəri dünya ədəbiyyatının ən çox oxunan kitablarından biri sayılır. Antuan de Sent-Ekzüperiın üslubu sadə görünsə də, mənaca son dərəcə zəngindir. Əsər bədii dilin gücünü və insan taleyinin mürəkkəbliyini birləşdirir. Hər bir fəsil oxucuda yeni sual və düşüncələr doğurur. Əsərdəki simvolizm oxucuya çoxqatlı məna qatları açır. Oxucu kitabı bitirdikdən sonra dünyaya fərqli gözlə baxmağa başlayır. Bu roman insan psixologiyasını və cəmiyyətin ziddiyyətlərini dəqiqliklə əks etdirir. Kitab boyunca gərginlik və maraq bir an belə azalmır. Kitab mütaliə mədəniyyətinin formalaşmasında mühüm rol oynayır. Əsər zaman keçdikcə yeni nəsillər tərəfindən yenidən kəşf edilir. Balaca Prens əsəri klassik ədəbiyyatın zirvələrindən biri hesab olunur. Kitabın son səhifəsi oxucuda uzun müddət unudulmayan təsir buraxır. Roman insan taleyinin, sevginin və mübarizənin dərin təhlilini verir.', 5.00, 'https://images.unsplash.com/photo-1544947950-fa07a98d237f?w=300&h=300&fit=crop'),
(14, 'Əli və Nino - Qurban Səid', 'Qurban Səid', 'Qurban Səidin Əli və Nino romanı 20-ci əsrin əvvəllərində Bakıda cərəyan edən əbədi və faciəvi bir sevgi dastanından bəhs edir. Əsər müfəssəl şəkildə Şərq və Qərb mədəniyyətlərinin toqquşmasını və sintezini işıqlandırır. Əli Xan Şirvanşir kübar bir müsəlman gənci, Nino Qipiani isə gürcü knyazının xristian qızıdır. Onların sevgisi dini və mədəni fərqliliklərə baxmayaraq bütün maneələri aşır. Hadisələr Birinci Dünya Müharibəsi, Azərbaycan Xalq Cümhuriyyətinin qurulması və bolşevik işğalı fonunda baş verir. Əli Vətəninə, adət-ənənələrinə bağlı bir bəy, Nino isə avropasayağı həyata üstünlük verən modern bir qadındır. Müəllif Bakının neft bumu dövründəki ictimai-siyasi həyatını, Qafqazın füsunkar təbiətini və adətlərini zəngin detallarla təsvir edir. Müharibə və siyasi çaxnaşmalar onların xoşbəxtliyinə kölgə salır. Əli ölkəsinin müstəqilliyi uğrunda bolşeviklərə qarşı mübarizəyə qoşulur. Gəncədəki körpü döyüşündə Əli Xan Vətəni uğrunda qəhrəmancasına həlak olur. Əsər yalnız bir sevgi hekayəsi deyil, həm də Azərbaycanın kəşfəfəşli tarixini göstərən tarixi bir sənəddir. Roman oxucuya vətənpərvərlik, sədaqət və mədəniyyətlərarası dialoq kimi mühüm mövzuları çatdırır. Kitab mütaliə mədəniyyətinin formalaşmasında mühüm rol oynayır. Roman boyunca hər bir personaj öz unikal inkişaf yolunu keçir. Əli və Nino oxunduqca insanın həyat və dəyərlər haqqında düşüncələri dərinləşir. Əsərin sonu oxucuda dərin düşüncə və hisslər buraxır. Əli və Nino əsəri klassik ədəbiyyatın zirvələrindən biri hesab olunur. Qurban Səidın yaradıcılığı dünya ədəbiyyatşünaslığında geniş tədqiq olunub. Bu kitab oxucuya həm zövq, həm də dərin düşüncə bəxş edir. Oxucu əsər boyu personajların taleyinə dərindən bağlanır. Qurban Səidın bu əsəri illər keçdikcə öz aktuallığını itirməmişdir. Əli və Nino əsəri dünya ədəbiyyatının ən çox oxunan kitablarından biri sayılır. Kitab oxucunu dərin düşüncələrə və mənəvi bir səyahətə aparır. Əsər zaman keçdikcə yeni nəsillər tərəfindən yenidən kəşf edilir. Hər bir mütaliəsevər bu kitabı kitabxanasında saxlamalıdır. Bu əsər həyatın mənası haqqında əbədi suallara işıq salır. Əli və Nino əsərinin təsiri kino, teatr və digər sənət sahələrinə də yayılmışdır. Qurban Səidın dili zəngin, obrazlı və son dərəcə təsiredicidir. Bu roman insan iradəsinin sınağa çəkildiyi anları təsvir edir. Qurban Səidın üslubu sadə görünsə də, mənaca son dərəcə zəngindir. Müəllifin yaratdığı atmosfer oxucunu əsərin dünyasına dərindən çəkir. Əsər bədii dilin gücünü və insan taleyinin mürəkkəbliyini birləşdirir. Roman insan taleyinin, sevginin və mübarizənin dərin təhlilini verir. Müəllifin təsvir bacarığı oxucunu hadisələrin canlı şahidinə çevirir. Əsər həm ədəbiyyatsevərlər, həm də tədqiqatçılar üçün dəyərli mənbədir. Kitab boyunca gərginlik və maraq bir an belə azalmır. Əsərdəki obrazların daxili dünyası incəliklə və ustalıqla işlənmişdir. Bu kitab tənqidçilər tərəfindən dəfələrlə yüksək qiymətləndirilmişdir. Roman fərdin cəmiyyətlə münasibətini bütün incəlikləri ilə göstərir. Əsərdə işlənən mövzular bu gün də öz aktuallığını qoruyur. Əsərdəki simvolizm oxucuya çoxqatlı məna qatları açır. Kitabdakı dialoqlar dərin fəlsəfi və psixoloji məna daşıyır. Kitabın son səhifəsi oxucuda uzun müddət unudulmayan təsir buraxır. Bu roman nəsillər boyu öz təsirini itirməyən əbədi bir dəyərdir. Kitabın strukturu diqqətlə düşünülmüş və mükəmməl qurulmuşdur. Bu roman insan psixologiyasını və cəmiyyətin ziddiyyətlərini dəqiqliklə əks etdirir. Əsərdəki hadisələr məntiqi ardıcıllıqla və ustalıqla qurulmuşdur. Qurban Səid bu romanda insan ruhunun ən dərin qatlarına işıq salır. Oxucu kitabı bitirdikdən sonra dünyaya fərqli gözlə baxmağa başlayır. Bu əsər dünya ədəbiyyatı tarixinin şah əsərlərindən biri kimi qəbul edilir.', 9.50, 'https://images.unsplash.com/photo-1532012197267-da84d127e765?w=300&h=300&fit=crop'),
(15, 'Simyaçı - Paulo Koelyo', 'Paulo Koelyo', 'Paulo Koelyonun Simyaçı romanı insanın öz taleyini və həyatın mənasını axtarışından bəhs edən ilhamverici bir fəlsəfi əsərdir. Əsərin baş qəhrəmanı Santyaqo adlı Əndəlüslü bir çobandır. O, gördüyü təkrar olunan yuxuların izi ilə Misir ehramlarında gizlədilmiş xəzinəni tapmaq üçün yola çıxır. Səyahəti boyunca Santyaqo müxtəlif insanlarla qarşılaşır: Qocalar hökmdarı Məlki-Sadiq, büllur satıcısı və sirli Simyaçı. Bu görüşlər ona ''Şəxsi Əfsanəsini'' gerçəkləşdirməyin və kainatın dilini öyrənməyin vacibliyini göstərir. Səhra gəzintisi zamanı Santyaqo daxili səsini dinləməyi və işarələri oxumağı öyrənir. O, Fatima adlı gənc bir qadına aşiq olur və həqiqi sevginin insanın məqsədinə mane olmadığını anlayır. Nəhayət Misir ehramlarına çatan Santyaqo xəzinənin əslində yola çıxdığı ilk yerdə — spansyada kilsənin həyətində olduğunu öyrənir. Bu kəşf ona göstərir ki, xəzinə gedilən yolun özündə və qazanılan təcrübələrdədir. Əsər oxucuya öz arzularının ardınca getməyi və heç vaxt ümidini itirməməyi tövsiyə edir. Paulo Koelyonun sadə və poetik dili romanı bütün dünyada bəşəri bir hit etmişdir. Kitab mənəvi oyanış və özünü kəşf etmə yolunda hər bir oxucuya bələdçilik edir. Bu kitab oxucuya həm zövq, həm də dərin düşüncə bəxş edir. Əsər zaman keçdikcə yeni nəsillər tərəfindən yenidən kəşf edilir. Kitab mütaliə mədəniyyətinin formalaşmasında mühüm rol oynayır. Bu roman insan iradəsinin sınağa çəkildiyi anları təsvir edir. Əsərin sonu oxucuda dərin düşüncə və hisslər buraxır. Roman boyunca hər bir personaj öz unikal inkişaf yolunu keçir. Simyaçı əsərinin təsiri kino, teatr və digər sənət sahələrinə də yayılmışdır. Oxucu kitabı bitirdikdən sonra dünyaya fərqli gözlə baxmağa başlayır. Bu kitab tənqidçilər tərəfindən dəfələrlə yüksək qiymətləndirilmişdir. Paulo Koelyo bu romanda insan ruhunun ən dərin qatlarına işıq salır. Bu roman nəsillər boyu öz təsirini itirməyən əbədi bir dəyərdir. Bu roman insan psixologiyasını və cəmiyyətin ziddiyyətlərini dəqiqliklə əks etdirir. Paulo Koelyoın yaradıcılığı dünya ədəbiyyatşünaslığında geniş tədqiq olunub. Paulo Koelyoın dili zəngin, obrazlı və son dərəcə təsiredicidir. Müəllifin yaratdığı atmosfer oxucunu əsərin dünyasına dərindən çəkir. Əsərdəki hadisələr məntiqi ardıcıllıqla və ustalıqla qurulmuşdur. Hər bir fəsil oxucuda yeni sual və düşüncələr doğurur. Oxucu əsər boyu personajların taleyinə dərindən bağlanır. Əsər bədii dilin gücünü və insan taleyinin mürəkkəbliyini birləşdirir. Kitabdakı dialoqlar dərin fəlsəfi və psixoloji məna daşıyır. Əsərdə işlənən mövzular bu gün də öz aktuallığını qoruyur. Kitab boyunca gərginlik və maraq bir an belə azalmır. Kitabın strukturu diqqətlə düşünülmüş və mükəmməl qurulmuşdur. Bu əsər həyatın mənası haqqında əbədi suallara işıq salır. Kitabın son səhifəsi oxucuda uzun müddət unudulmayan təsir buraxır. Paulo Koelyoın üslubu sadə görünsə də, mənaca son dərəcə zəngindir. Roman fərdin cəmiyyətlə münasibətini bütün incəlikləri ilə göstərir. Əsər həm ədəbiyyatsevərlər, həm də tədqiqatçılar üçün dəyərli mənbədir. Roman insan taleyinin, sevginin və mübarizənin dərin təhlilini verir. Simyaçı oxunduqca insanın həyat və dəyərlər haqqında düşüncələri dərinləşir. Əsərdəki simvolizm oxucuya çoxqatlı məna qatları açır. Simyaçı əsəri klassik ədəbiyyatın zirvələrindən biri hesab olunur. Əsərdəki obrazların daxili dünyası incəliklə və ustalıqla işlənmişdir. Paulo Koelyoın bu əsəri illər keçdikcə öz aktuallığını itirməmişdir. Bu əsər dünya ədəbiyyatı tarixinin şah əsərlərindən biri kimi qəbul edilir. Müəllifin təsvir bacarığı oxucunu hadisələrin canlı şahidinə çevirir. Kitab oxucunu dərin düşüncələrə və mənəvi bir səyahətə aparır. Əsərdəki hər bir təfərrüat müəllifin böyük ustalığından xəbər verir.', 8.50, 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=300&h=300&fit=crop'),
(16, '1984 - Corc Oruell', 'Corc Oruell', 'Corc Oruellin 1984 romanı antitotalitar ədəbiyyatın ən qüdrətli şahəsərlərindən biridir. Əsərdə Okeaniya adlı distopik bir dövlətdə insani azadlıqların, təfəkkürün və fərdiliyin tamamilə məhv edildiyi bir rejim təsvir olunur. Böyük Qardaşın rəhbərlik etdiyi Partiya hər bir vətəndaşı teleekranlar vasitəsilə 24 saat nəzarətdə saxlayır. Baş qəhrəman Uinston Smit Həqiqət Nazirliyində çalışır və vəzifəsi tarixi rejimə uyğun olaraq yenidən yazmaqdır. O, daxilən Partiyanın yalanlarına və təzyiqlərinə qarşı nifrət bəsləyir. Uinston gizlicə bir gündəlik tutur və bu günəş işığına çıxmayan fikirlərini oraya yazır. O, Culiya adlı gənc bir qadınla tanış olur və onlar arasında gizli bir sevgi münasibəti başlayır. Uinston və Culiya rejimin qadağalarına baxmayaraq azadlıq və insanlıq hisslərini yaşamağa çalışırlar. Lakin Sevgi Nazirliyi və Fikir Polisi onları addım-addım izləyir. Nəhayət onlar həbs olunurlar və Uinston dəhşətli işgəncələrə məruz qalır. 101-ci otaqda Uinston özünün ən böyük qorxusu ilə üz-üzə qoyulur və Culiyaya xəyanət etməyə məcbur edilir. Rejim onun ruhunu və iradəsini tamamilə qırır. Əsərin sonunda Uinston artıq Böyük Qardaşı sevdiyini anlayır. Oruellin bu romanı siyasi nəzarət, təbliğat və dilin manipulyasiyası haqqında xəbərdarlıq xarakterli böyük bir sənəddir. Roman insan taleyinin, sevginin və mübarizənin dərin təhlilini verir. Hər bir fəsil oxucuda yeni sual və düşüncələr doğurur. Əsərdəki obrazların daxili dünyası incəliklə və ustalıqla işlənmişdir. Corc Oruellın bu əsəri illər keçdikcə öz aktuallığını itirməmişdir. Hər bir mütaliəsevər bu kitabı kitabxanasında saxlamalıdır. Corc Oruellın dili zəngin, obrazlı və son dərəcə təsiredicidir. Bu roman nəsillər boyu öz təsirini itirməyən əbədi bir dəyərdir. Bu əsər dünya ədəbiyyatı tarixinin şah əsərlərindən biri kimi qəbul edilir. Corc Oruell bu romanda insan ruhunun ən dərin qatlarına işıq salır. Bu kitab oxucuya həm zövq, həm də dərin düşüncə bəxş edir. Roman boyunca hər bir personaj öz unikal inkişaf yolunu keçir. Əsər zaman keçdikcə yeni nəsillər tərəfindən yenidən kəşf edilir. Əsərdə işlənən mövzular bu gün də öz aktuallığını qoruyur. Kitab oxucunu dərin düşüncələrə və mənəvi bir səyahətə aparır. Oxucu kitabı bitirdikdən sonra dünyaya fərqli gözlə baxmağa başlayır. Kitab mütaliə mədəniyyətinin formalaşmasında mühüm rol oynayır. Bu kitab tənqidçilər tərəfindən dəfələrlə yüksək qiymətləndirilmişdir. Əsərin sonu oxucuda dərin düşüncə və hisslər buraxır. Bu əsər həyatın mənası haqqında əbədi suallara işıq salır. Bu roman insan psixologiyasını və cəmiyyətin ziddiyyətlərini dəqiqliklə əks etdirir. Müəllifin təsvir bacarığı oxucunu hadisələrin canlı şahidinə çevirir. Əsərdəki hər bir təfərrüat müəllifin böyük ustalığından xəbər verir. 1984 əsəri klassik ədəbiyyatın zirvələrindən biri hesab olunur. Roman fərdin cəmiyyətlə münasibətini bütün incəlikləri ilə göstərir. 1984 əsərinin təsiri kino, teatr və digər sənət sahələrinə də yayılmışdır. Müəllifin yaratdığı atmosfer oxucunu əsərin dünyasına dərindən çəkir. Əsər həm ədəbiyyatsevərlər, həm də tədqiqatçılar üçün dəyərli mənbədir. Kitab boyunca gərginlik və maraq bir an belə azalmır. 1984 oxunduqca insanın həyat və dəyərlər haqqında düşüncələri dərinləşir. Kitabdakı dialoqlar dərin fəlsəfi və psixoloji məna daşıyır. Əsərdəki simvolizm oxucuya çoxqatlı məna qatları açır. Corc Oruellın üslubu sadə görünsə də, mənaca son dərəcə zəngindir. 1984 əsəri dünya ədəbiyyatının ən çox oxunan kitablarından biri sayılır. Kitabın strukturu diqqətlə düşünülmüş və mükəmməl qurulmuşdur. Kitabın son səhifəsi oxucuda uzun müddət unudulmayan təsir buraxır. Corc Oruellın yaradıcılığı dünya ədəbiyyatşünaslığında geniş tədqiq olunub.', 9.00, 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=300&h=300&fit=crop'),
(17, 'Çevrilmə və Digər Hekayələr - Frans Kafka', 'Frans Kafka', 'Frans Kafkanın bu məcmuəsi müəllifin ən görkəmli absurd və ekspressionist əsərlərini bir araya gətirir. Kitabda ''Çevrilmə'' povesti ilə yanaşı, ''Məhkəmə'', ''Cəza Koloniyasında'' və müxtəlif qısa hekayələr yer alır. Kafka insan psixologiyasının ən qaranlıq, müammalı və çarəsiz tərəflərini qələmə alır. Hekayələrin ana xəttini fərdin bürokratiya, cəmiyyət və ailə qarşısındakı acizliyi təşkil edir. Qəhrəmanlar səbəbini bilmədikləri günahlandırılmalara və cəzalara məruz qalırlar. Müəllifin minimalist və sadə dili təsvir olunan hadisələrin dəhşətini daha da qabardır. Kafkanın yaradıcılığı 20-ci əsr insanının özünə və dünyaya özgələşməsinin ən dəqiq güzgüsüdür. Əsərlərdəki qasvetli atmosfer oxucuda dərin boğuntu və düşüncə yaradır. Bu məcmuə modern ədəbiyyatın bünövrə daşlarından biridir. Çevrilmə və Digər Hekayələr əsəri klassik ədəbiyyatın zirvələrindən biri hesab olunur. Bu kitab tənqidçilər tərəfindən dəfələrlə yüksək qiymətləndirilmişdir. Oxucu əsər boyu personajların taleyinə dərindən bağlanır. Kitabın son səhifəsi oxucuda uzun müddət unudulmayan təsir buraxır. Çevrilmə və Digər Hekayələr əsəri dünya ədəbiyyatının ən çox oxunan kitablarından biri sayılır. Bu əsər dünya ədəbiyyatı tarixinin şah əsərlərindən biri kimi qəbul edilir. Kitabın strukturu diqqətlə düşünülmüş və mükəmməl qurulmuşdur. Frans Kafkaın üslubu sadə görünsə də, mənaca son dərəcə zəngindir. Frans Kafkaın dili zəngin, obrazlı və son dərəcə təsiredicidir. Əsərdəki obrazların daxili dünyası incəliklə və ustalıqla işlənmişdir. Əsərdəki simvolizm oxucuya çoxqatlı məna qatları açır. Çevrilmə və Digər Hekayələr oxunduqca insanın həyat və dəyərlər haqqında düşüncələri dərinləşir. Roman boyunca hər bir personaj öz unikal inkişaf yolunu keçir. Bu kitab oxucuya həm zövq, həm də dərin düşüncə bəxş edir. Kitab oxucunu dərin düşüncələrə və mənəvi bir səyahətə aparır. Hər bir fəsil oxucuda yeni sual və düşüncələr doğurur. Kitab mütaliə mədəniyyətinin formalaşmasında mühüm rol oynayır. Çevrilmə və Digər Hekayələr əsərinin təsiri kino, teatr və digər sənət sahələrinə də yayılmışdır. Əsərin sonu oxucuda dərin düşüncə və hisslər buraxır. Bu roman insan psixologiyasını və cəmiyyətin ziddiyyətlərini dəqiqliklə əks etdirir. Bu əsər həyatın mənası haqqında əbədi suallara işıq salır. Kitabdakı dialoqlar dərin fəlsəfi və psixoloji məna daşıyır. Müəllifin yaratdığı atmosfer oxucunu əsərin dünyasına dərindən çəkir. Müəllifin təsvir bacarığı oxucunu hadisələrin canlı şahidinə çevirir. Frans Kafka bu romanda insan ruhunun ən dərin qatlarına işıq salır. Kitab boyunca gərginlik və maraq bir an belə azalmır. Hər bir mütaliəsevər bu kitabı kitabxanasında saxlamalıdır. Əsər zaman keçdikcə yeni nəsillər tərəfindən yenidən kəşf edilir. Bu roman insan iradəsinin sınağa çəkildiyi anları təsvir edir. Əsərdə işlənən mövzular bu gün də öz aktuallığını qoruyur. Roman fərdin cəmiyyətlə münasibətini bütün incəlikləri ilə göstərir. Frans Kafkaın bu əsəri illər keçdikcə öz aktuallığını itirməmişdir. Əsər həm ədəbiyyatsevərlər, həm də tədqiqatçılar üçün dəyərli mənbədir. Oxucu kitabı bitirdikdən sonra dünyaya fərqli gözlə baxmağa başlayır. Roman insan taleyinin, sevginin və mübarizənin dərin təhlilini verir. Əsərdəki hadisələr məntiqi ardıcıllıqla və ustalıqla qurulmuşdur. Əsər bədii dilin gücünü və insan taleyinin mürəkkəbliyini birləşdirir. Bu roman nəsillər boyu öz təsirini itirməyən əbədi bir dəyərdir. Frans Kafkaın yaradıcılığı dünya ədəbiyyatşünaslığında geniş tədqiq olunub. Əsərdəki hər bir təfərrüat müəllifin böyük ustalığından xəbər verir. Çevrilmə və Digər Hekayələr əsəri klassik ədəbiyyatın zirvələrindən biri hesab olunur.', 7.80, 'https://images.unsplash.com/photo-1543002588-bfa74002ed7e?w=300&h=300&fit=crop'),
(18, 'Martin İden - Cek London', 'Cek London', 'Cek Londonun Martin İden romanı sadə bir dənizçinin yazıçı olmaq uğrunda apardığı amansız mübarizədən və mənəvi dramından bəhs edir. Baş qəhrəman Martin İden varlı və kübar bir ailədən olan Rut Morsz adlı qıza aşiq olur. O, Rutun mənsub olduğu yüksək cəmiyyətə layiq olmaq üçün gecə-gündüz mütaliə edir və özünü təkmilləşdirir. Martin böyük çətinliklərə, ac-yalavac günlərə baxmayaraq yazıçılıq istedadını sübut etməyə çalışır. İllərlə çəkdiyi əziyyətlərdən sonra o, nəhayət böyük şöhrət və sərvət qazanır. Lakin uğur qazandıqdan sonra Martin burjua cəmiyyətinin ikiüzlülüyünü və riyakarlığını görür. Onu vaxtilə savadsız və kasıb olduğu üçün rədd edən insanlar indi onun şöhrətinə pərəstiş edirlər. Martin İden dərin mənəvi böhran və tənhalıq keçirir. İnsanlara və həyata olan inamını itirən Martin okeana tullanaraq intihar edir. Roman fərdi mübarizə, azadlıq və cəmiyyətin puçluğu haqqında unudulmaz bir şahəsərdir. Əsər zaman keçdikcə yeni nəsillər tərəfindən yenidən kəşf edilir. Oxucu əsər boyu personajların taleyinə dərindən bağlanır. Əsərdəki hadisələr məntiqi ardıcıllıqla və ustalıqla qurulmuşdur. Cek Londonın bu əsəri illər keçdikcə öz aktuallığını itirməmişdir. Kitab mütaliə mədəniyyətinin formalaşmasında mühüm rol oynayır. Kitab oxucunu dərin düşüncələrə və mənəvi bir səyahətə aparır. Martin İden əsəri dünya ədəbiyyatının ən çox oxunan kitablarından biri sayılır. Hər bir mütaliəsevər bu kitabı kitabxanasında saxlamalıdır. Bu roman insan psixologiyasını və cəmiyyətin ziddiyyətlərini dəqiqliklə əks etdirir. Bu kitab oxucuya həm zövq, həm də dərin düşüncə bəxş edir. Oxucu kitabı bitirdikdən sonra dünyaya fərqli gözlə baxmağa başlayır. Bu kitab tənqidçilər tərəfindən dəfələrlə yüksək qiymətləndirilmişdir. Əsər bədii dilin gücünü və insan taleyinin mürəkkəbliyini birləşdirir. Roman boyunca hər bir personaj öz unikal inkişaf yolunu keçir. Bu əsər həyatın mənası haqqında əbədi suallara işıq salır. Roman fərdin cəmiyyətlə münasib