USE kadr_fullstack;

ON DUPLICATE KEY UPDATE title = VALUES(title), author = VALUES(author), description = VALUES(description), price = VALUES(price), picture = VALUES(picture);

ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), video_url = VALUES(video_url), picture = VALUES(picture);
